package com.novacommerce.order.api; import com.novacommerce.order.application.CartService; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/cart")public class CartController{private final CartService carts;public CartController(CartService c){carts=c;}@GetMapping OrderDtos.CartResponse get(@AuthenticationPrincipal Jwt j){return OrderDtos.CartResponse.from(carts.get(owner(j)));}@PostMapping("/items")OrderDtos.CartResponse add(@AuthenticationPrincipal Jwt j,@Valid@RequestBody OrderDtos.ItemRequest r){return OrderDtos.CartResponse.from(carts.add(owner(j),r.variantId(),r.quantity()));}@PatchMapping("/items/{id}")OrderDtos.CartResponse update(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid@RequestBody OrderDtos.QuantityRequest r){return OrderDtos.CartResponse.from(carts.update(owner(j),id,r.quantity()));}@DeleteMapping("/items/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void remove(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){carts.remove(owner(j),id);}@DeleteMapping@ResponseStatus(HttpStatus.NO_CONTENT)void clear(@AuthenticationPrincipal Jwt j){carts.clear(owner(j));}static UUID owner(Jwt j){return UUID.fromString(j.getSubject());}}
